import { createServer } from 'node:http';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';

const frontend = '/Users/jamie/development/exposed-posthog-development/frontend';
const require = createRequire(`${frontend}/package.json`);
const { chromium } = require('playwright');
const requests = [];
const collector = createServer((req, res) => {
  requests.push(req.url);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Headers', '*');
  res.setHeader('Content-Type', 'application/json');
  res.end(JSON.stringify(req.url.includes('flags') ? { featureFlags: {} } : { status: 1 }));
});
collector.listen(0, '127.0.0.1');
await once(collector, 'listening');
const collectorUrl = `http://127.0.0.1:${collector.address().port}`;
const browser = await chromium.launch({ headless: true });
const results = [];
try {
  for (const mode of ['development-configured', 'development-unconfigured', 'production-configured']) {
    const production = mode.startsWith('production');
    const configured = !mode.includes('unconfigured');
    const port = production ? 5189 : 5188;
    const origin = `http://127.0.0.1:${port}`;
